// Reset masks and RDMA buffers so previously masked ranks can re-join. Collective: all surviving ranks must call simultaneously. Resets RDMA buffers via a cross-rank barrier and sets all masks to active. Does NOT reset the async error flag — call [Group.ErrorClear] separately. Note: this API is for re-admitting a delayed rank within the same communicator. Rank replacement requires a new communicator (e.g., ncclCommGrow) and a new EP group. Requires enable_mask=true in the group config.
//
//   - epGroup: in EP group with masking enabled
//   - stream: in CUDA stream
//
// Wraps ncclEpMaskClean.
func MaskClean(epGroup Group, stream driver.Stream) error {
	if err := checkLibSym("ncclEpMaskClean"); err != nil {
		return err
	}
	return toError(fnMaskClean(epGroup, stream), "ncclEpMaskClean")
}

// MaskQuery copies the rank mask to a device array asynchronously.
//
// Query the active-mask status of all ranks. Copies the mask buffer to a user-provided device tensor. Requires enable_mask=true in the group config.
//
//   - epGroup: in EP group with masking enabled
//   - maskStatus: out Device pointer to int[nRanks]. 1 = active, 0 = masked (failed)
//   - stream: in CUDA stream
//
// Wraps ncclEpMaskQuery.
func MaskQuery(epGroup Group, maskStatus nccl.Buffer, stream driver.Stream) error {
	if err := checkLibSym("ncclEpMaskQuery"); err != nil {
		return err
	}
	return toError(fnMaskQuery(epGroup, maskStatus, stream), "ncclEpMaskQuery")
}

// MaskUpdate copies a host rank mask to the device asynchronously.
//
// Set the mask for all ranks at once. Requires enable_mask=true in the group config.
//
//   - epGroup: in EP group with masking enabled
//   - mask: in Host pointer to int[nRanks]. 1 = active, 0 = masked (failed)
//   - stream: in CUDA stream
//
// Wraps ncclEpMaskUpdate.
func MaskUpdate(epGroup Group, mask *int32, stream driver.Stream) error {
	if err := checkLibSym("ncclEpMaskUpdate"); err != nil {
		return err
	}
	return toError(fnMaskUpdate(epGroup, mask, stream), "ncclEpMaskUpdate")
}

// TensorAlloc allocates a tensor descriptor and copies its dimensions.
//
// Allocate a tensor descriptor sufficient to represent the requested shape.
//
//   - ndim: in Number of dimensions (> 0)
//   - datatype: in Element type
//   - sizes: in Array of `ndim` dimension sizes
//   - config: in Optional allocation configuration. NULL = defaults
//
// Wraps ncclEpTensorAlloc.
func TensorAlloc(ndim uint32, datatype nccl.DataType, sizes *uint, config *TensorAllocConfig) (*Tensor, error) {
	if err := checkLibSym("ncclEpTensorAlloc"); err != nil {
		var zero *Tensor
		return zero, err
	}
	out := slotTensorAlloc.get()
	defer slotTensorAlloc.put(out)
	if err := toError(fnTensorAlloc(out, ndim, datatype, sizes, config), "ncclEpTensorAlloc"); err != nil {
		var zero *Tensor
		return zero, err
	}
	return *out, nil
}

var slotTensorAlloc outSlot[*Tensor]

// TensorDestroy releases a descriptor returned by TensorAlloc.
//
// Release a descriptor previously returned by [TensorAlloc].
//
//   - tensor: in Pointer returned by [TensorAlloc]. NULL is accepted
//
// Wraps ncclEpTensorDestroy.
func TensorDestroy(tensor *Tensor) error {
	if err := checkLibSym("ncclEpTensorDestroy"); err != nil {
		return err
	}
	return toError(fnTensorDestroy(tensor), "ncclEpTensorDestroy")
}

// UpdateHandle updates a handle's routing metadata on the given stream.
//
// Per-step collective: prepare the handle for the given top-k routing decisions. Must be called after [Group.InitHandle] and before [Handle.Dispatch].
//
//   - handle: in Handle from [Group.InitHandle]
//   - topkIdx: in [num_tokens, top_k]; ncclInt32 or ncclInt64
//   - layoutInfo: in/out, optional Named local tensors (NULL = none provided). See [LayoutInfo] for the fields populated at handle time and the layouts each applies to. LL mode: must be NULL
//   - stream: in CUDA stream
//
// Wraps ncclEpUpdateHandle.
func UpdateHandle(handle Handle, topkIdx *Tensor, layoutInfo *LayoutInfo, stream driver.Stream) error {
	if err := checkLibSym("ncclEpUpdateHandle"); err != nil {
		return err
	}
	return toError(fnUpdateHandle(handle, topkIdx, layoutInfo, stream), "ncclEpUpdateHandle")
}
